    public static bool TryTranslate(ModSnapshot snapshot, string original, out string translated)
    {
        translated = "";
        if (!snapshot.Documents.TryGetValue("meta.json", out var meta)) return false;
        var name = meta["Name"]?.GetValue<string>();
        var author = meta["Author"]?.GetValue<string>();
        if (!string.Equals(name?.Trim(), "Rue+", StringComparison.OrdinalIgnoreCase)
            || author?.Contains("Elegy", StringComparison.OrdinalIgnoreCase) != true) return false;
        var key = original.Replace("\r\n", "\n", StringComparison.Ordinal).Replace('\r', '\n').Trim();
        return RuePlus.TryGetValue(key, out translated!);
    }
